sys_script.script:
(function executeRule(current, previous) {

    // Catalog Item Sys IDs
    var AMBULANCE_ITEM_ID = '1c371d7847d0d310273a565a516d43ea';
    var WHEELCHAIR_ITEM_ID = '6e08693c4794d310273a565a516d432e';

    var catalogItemId = current.getValue('cat_item');
    var chargeType = '';

    if (catalogItemId == AMBULANCE_ITEM_ID) {
        chargeType = 'ambulance';
    } else if (catalogItemId == WHEELCHAIR_ITEM_ID) {
        chargeType = 'wheelchair_assistance';
    } else {
        return;
    }

    // Get RITM variables
    var patientId = current.variables.requested_for.toString();
    var hospitalId = current.variables.hospital.toString();
    var admissionId = current.variables.related_admission.toString();


    if (!patientId || !hospitalId || !admissionId) {
        return;
    }
    // Get RITM price
    var amount = current.getValue('price');
    if (!amount || parseFloat(amount) <= 0) {
        return;
    }
    // Prevent duplicate Charge Line
    var charge = new GlideRecord(
        'x_2223823_apollo_0_charge_line'
    );

    charge.addQuery('source_table', 'sc_req_item');
    charge.addQuery('source_record', current.getUniqueValue());
    charge.query();
    if (charge.next()) {
        return;
    }
    // Find Admission record
    var admission = new GlideRecord(
        'x_2223823_apollo_0_admissions'
    );

    if (!admission.get(admissionId)) {
        return;
    }
    // Get Invoice from Admission
    var invoiceId = admission.getValue('final_invoice');
    if (!invoiceId) {
        return;
    }

    // Create Charge Line
    charge.initialize();

    charge.setValue('patient', patientId);
    charge.setValue('hospital', hospitalId);
    charge.setValue('invoice', invoiceId);
    charge.setValue('amount', amount);
    charge.setValue('charge_type', 'service');
    charge.setValue('status', 'invoiced');

    charge.setValue(
        'description',
        chargeType == 'ambulance' ?
        'Ambulance Service Charge' :
        'Wheelchair Assistance Charge'
    );

    charge.setValue('source_table', 'sc_req_item');
    charge.setValue('source_record', current.getUniqueValue());

    var sys_ids = charge.insert();

})(current, previous);
